from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    row_lines = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if color != background and count > w / 2:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color != background and count > h / 2:
            col_lines.append(c)

    result = []
    for r1, r2 in zip(row_lines, row_lines[1:]):
        outrow = []
        for c1, c2 in zip(col_lines, col_lines[1:]):
            corners = (grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2])
            outrow.append(corners[0] if len(set(corners)) == 1 else background)
        result.append(outrow)
    return result
